package cn.binbin.crm;

import jakarta.validation.constraints.*;
import java.util.*;

import org.springframework.stereotype.Service;
import static cn.binbin.crm.TradeService.*;

@Service
public class AiQualityService {
 public record PromptInput(@NotBlank String taskType,@NotBlank @Size(max=100) String title,@NotBlank @Size(max=4000) String instruction){}
 public record ReleaseInput(@NotNull UUID promptId,boolean enabled,@Min(0) @Max(100) int rolloutPercent,@Min(0) long expectedVersion){}
 public record PolicyInput(@NotNull @Size(max=20) List<@NotBlank @Size(min=2,max=64) String> sensitiveTerms,boolean strictFacts,@Min(0) long expectedVersion){}
 public record ReviewInput(@NotNull @Pattern(regexp="ACCEPTED|REJECTED") String decision,@Min(1) @Max(5) int factualScore,@Min(1) @Max(5) int usefulnessScore,@NotBlank @Size(min=10,max=1000) String notes,@Min(0) long expectedVersion){}
 public record RuleTestInput(@NotBlank @Size(max=12000) String source,@NotBlank @Size(max=12000) String output){}
 public record Snapshot(UUID promptId,long releaseVersion,long policyVersion,String instruction,List<String> sensitiveTerms,boolean strictFacts){}
 public record Check(String status,List<String> findings,String text){}
 final P3Base b;
 public AiQualityService(P3Base b){this.b=b;}
 static int cohort(UUID tenant,String task,UUID prompt){return Math.floorMod(Objects.hash(tenant,task,prompt),100);}
 private AuthService.Actor actor(AuthService.Session s,boolean admin,boolean write){var a=b.auth.actor(s);if(a.supportGrantId()!=null||(admin?!a.tenant().roles().contains("TENANT_ADMIN"):!a.p4Access().aiUse()))throw ApiError.forbidden("无 AI 管理权限");if(write&&!a.tenant().subscriptionEnd().isAfter(java.time.Instant.now()))throw ApiError.forbidden("订阅到期，当前只可查看");b.context(a.tenant().id());return a;}
 @SuppressWarnings("unchecked") private List<String> terms(Object raw){if(raw==null)return List.of();try{return b.data.json.readValue(raw.toString(),List.class);}catch(Exception e){throw new IllegalStateException("AI sensitive policy invalid",e);}}
 private Map<String,Object> policy(UUID tenant){var r=b.rows("SELECT * FROM crm_ai_quality_policy WHERE tenant_id=:tenant",map("tenant",tenant));var row=r.isEmpty()?map("sensitiveTerms",List.of(),"strictFacts",true,"version",0):r.getFirst();if(!(row.get("sensitiveTerms") instanceof List))row.put("sensitiveTerms",terms(row.get("sensitiveTerms")));return row;}
 public Snapshot snapshot(AuthService.Session s,String type){AiScenarioService.task(type);return b.tx.execute(st->{var a=actor(s,false,false);var r=b.one("SELECT r.*,v.instruction FROM sys_ai_prompt_release r JOIN sys_ai_prompt_version v ON v.id=r.prompt_id WHERE r.task_type=:task",map("task",type));UUID prompt=(UUID)r.get("promptId");if(!Boolean.TRUE.equals(r.get("enabled"))||cohort(a.tenant().id(),type,prompt)>=number(r,"rolloutPercent"))throw ApiError.conflict("此 AI 场景尚未开放给当前企业，请由产品方调整灰度发布");var p=policy(a.tenant().id());return new Snapshot(prompt,number(r,"version"),number(p,"version"),String.valueOf(r.get("instruction")),(List<String>)p.get("sensitiveTerms"),Boolean.TRUE.equals(p.get("strictFacts")));});}
 public String redactCurrent(AuthService.Session s,String text){return b.tx.execute(st->{var a=actor(s,false,false);var p=policy(a.tenant().id());String out=AiRedaction.redact(text);for(Object term:(List<?>)p.get("sensitiveTerms"))out=out.replace(String.valueOf(term),"[企业敏感词已隐藏]");return out;});}
 public String redact(String text,Snapshot snapshot){String out=AiRedaction.redact(text);for(String term:snapshot.sensitiveTerms())out=out.replace(term,"[企业敏感词已隐藏]");return out;}
 public void stamp(UUID tenant,UUID run,Snapshot s,String sourceHash){b.tx.executeWithoutResult(st->{b.context(tenant);b.db.update("UPDATE crm_ai_run SET prompt_version_id=:prompt,release_version=:release,quality_policy_version=:policy,source_hash=:source WHERE tenant_id=:tenant AND id=:run AND prompt_version_id IS NULL",map("prompt",s.promptId(),"release",s.releaseVersion(),"policy",s.policyVersion(),"source",sourceHash,"tenant",tenant,"run",run));});}
 public boolean current(AuthService.Session session,String task,Map<String,Object> run){try{var s=snapshot(session,task);return s.promptId().equals(run.get("promptVersionId"))&&s.releaseVersion()==number(run,"releaseVersion")&&s.policyVersion()==number(run,"qualityPolicyVersion");}catch(ApiError e){return false;}}
 static Check inspect(String source,String output,boolean strict,List<String> sensitive){var findings=new ArrayList<String>();String clean=AiRedaction.redact(output);boolean blocked=false;for(String term:sensitive)if(clean.contains(term)){clean=clean.replace(term,"[企业敏感词已隐藏]");blocked=true;}
  if(!clean.equals(output)||clean.contains("已隐藏"))findings.add("输出含脱敏标记，需核实上下文完整性");
  if(blocked)findings.add("输出命中企业敏感词，禁止采纳与执行");
  if(strict){var match=java.util.regex.Pattern.compile("(?:\\d{4}-\\d{2}-\\d{2})|(?:[¥￥]\\s*\\d+(?:\\.\\d+)?)|(?:\\d+(?:\\.\\d+)?\\s*(?:万元|亿元|元|%))").matcher(clean);while(match.find()){if(!source.contains(match.group())){findings.add("输出含来源中未找到的日期、金额或比例，需人工核实");break;}}}
  if(clean.matches("(?s).*(?:已经批准|已自动审批|已完成付款|已自动创建|保证.*(?:赔偿|到账|解决)).*"))findings.add("输出可能包含未经确认的业务结果或承诺");
  return new Check(blocked?"BLOCKED":findings.isEmpty()?"PASS":"REVIEW",List.copyOf(findings),clean);
 }
 public void evaluate(UUID tenant,UUID run,Snapshot s,String source,String text,boolean releaseCurrent){var result=inspect(source,text,s.strictFacts(),s.sensitiveTerms());var findings=new ArrayList<>(result.findings());if(!releaseCurrent)findings.add("调用期间提示词或企业策略已变化，当前结果禁止执行");String status=releaseCurrent?result.status():"BLOCKED";b.tx.executeWithoutResult(st->{b.context(tenant);b.db.update("UPDATE crm_ai_run SET quality_status=:state,quality_findings=cast(:findings AS jsonb),result_text=:text WHERE tenant_id=:tenant AND id=:run AND status='SUCCEEDED'",map("state",status,"findings",b.json(findings),"text",result.text(),"tenant",tenant,"run",run));});}
 public Object settings(AuthService.Session s){return b.tx.execute(st->{var a=actor(s,true,false);return policy(a.tenant().id());});}
 public Object savePolicy(AuthService.Session s,PolicyInput input,UUID trace){return b.tx.execute(st->{var a=actor(s,true,true);b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",a.tenant().id()),UUID.class);var old=policy(a.tenant().id());if(number(old,"version")!=input.expectedVersion())throw ApiError.conflict("敏感信息策略已变化，请刷新");var terms=input.sensitiveTerms().stream().map(String::strip).distinct().toList();if(terms.stream().anyMatch(v->v.length()<2))throw ApiError.bad("敏感词至少两个字符");b.db.update("INSERT INTO crm_ai_quality_policy(tenant_id,sensitive_terms,strict_facts,version) VALUES(:tenant,cast(:terms AS jsonb),:strict,1) ON CONFLICT(tenant_id) DO UPDATE SET sensitive_terms=excluded.sensitive_terms,strict_facts=excluded.strict_facts,version=crm_ai_quality_policy.version+1,updated_at=now()",map("tenant",a.tenant().id(),"terms",b.json(terms),"strict",input.strictFacts()));b.audit(a,"AI_QUALITY_POLICY_UPDATED","AI_POLICY",a.tenant().id(),input.expectedVersion()+1,trace);return policy(a.tenant().id());});}
 public Object review(AuthService.Session s,Map<String,Object> run,ReviewInput i,UUID trace){return b.tx.execute(st->{var a=actor(s,false,true);if(!a.p4Access().aiReview())throw ApiError.forbidden("仅主管可复核 AI 输出");if(!"SUCCEEDED".equals(run.get("status")))throw ApiError.conflict("仅可复核已完成的调用");if(i.decision().equals("ACCEPTED")&&"BLOCKED".equals(run.get("qualityStatus")))throw ApiError.conflict("策略阻断的结果不能采纳，请重新生成");int n=b.db.update("UPDATE crm_ai_run SET review_status=:decision,review_version=review_version+1 WHERE tenant_id=:tenant AND id=:run AND review_version=:version",map("decision",i.decision(),"tenant",a.tenant().id(),"run",run.get("id"),"version",i.expectedVersion()));if(n!=1)throw ApiError.conflict("复核结果已变化，请刷新");b.db.update("INSERT INTO crm_ai_evaluation(id,tenant_id,run_id,reviewer_member_id,decision,factual_score,usefulness_score,notes) VALUES(:id,:tenant,:run,:member,:decision,:facts,:useful,:notes)",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"run",run.get("id"),"member",a.tenant().memberId(),"decision",i.decision(),"facts",i.factualScore(),"useful",i.usefulnessScore(),"notes",AiScenarioService.clean(i.notes(),1000)));b.audit(a,"AI_QUALITY_REVIEWED","AI_RUN",(UUID)run.get("id"),i.expectedVersion()+1,trace);return map("saved",true);});}
 public Object platform(AuthService.Session s){return b.tx.execute(st->{b.auth.platform(s);return map("tasks",AiScenarioService.TASKS,"versions",b.rows("SELECT * FROM sys_ai_prompt_version ORDER BY created_at DESC,id",Map.of()),"releases",b.rows("SELECT * FROM sys_ai_prompt_release ORDER BY task_type",Map.of()),"notice","离线规则检查不能证明模型无幻觉。真实模型质量需在企业试点中逐条复核；回滚只调整后续调用，不撤销业务记录。");});}
 private void audit(AuthService.Session s,String action,UUID target,UUID trace){b.db.update("INSERT INTO sys_platform_audit(id,actor_user_id,action,target_id,trace_id) VALUES(:id,:actor,:action,:target,:trace)",map("id",UUID.randomUUID(),"actor",s.userId(),"action",action,"target",target,"trace",trace));}
 public Object createPrompt(AuthService.Session s,PromptInput i,UUID trace){AiScenarioService.task(i.taskType());return b.tx.execute(st->{b.auth.platform(s);UUID id=UUID.randomUUID();b.db.update("INSERT INTO sys_ai_prompt_version(id,task_type,title,instruction,created_by_user_id) VALUES(:id,:task,:title,:instruction,:actor)",map("id",id,"task",i.taskType(),"title",AiScenarioService.clean(i.title(),100),"instruction",AiScenarioService.clean(i.instruction(),4000),"actor",s.userId()));audit(s,"AI_PROMPT_VERSION_CREATED",id,trace);return map("id",id);});}
 public Object release(AuthService.Session s,String task,ReleaseInput i,boolean rollback,UUID trace){AiScenarioService.task(task);return b.tx.execute(st->{b.auth.platform(s);var old=b.one("SELECT * FROM sys_ai_prompt_release WHERE task_type=:task FOR UPDATE",map("task",task));UUID target=rollback?(UUID)old.get("previousPromptId"):i.promptId();if(target==null)throw ApiError.conflict("没有可回滚版本");b.one("SELECT id FROM sys_ai_prompt_version WHERE id=:id AND task_type=:task",map("id",target,"task",task));int n=b.db.update("UPDATE sys_ai_prompt_release SET previous_prompt_id=CASE WHEN prompt_id<>:id THEN prompt_id ELSE previous_prompt_id END,prompt_id=:id,enabled=:enabled,rollout_percent=:percent,version=version+1,updated_at=now() WHERE task_type=:task AND version=:version",map("id",target,"enabled",i.enabled(),"percent",i.rolloutPercent(),"task",task,"version",i.expectedVersion()));if(n!=1)throw ApiError.conflict("发布状态已变化，请刷新");audit(s,rollback?"AI_PROMPT_ROLLED_BACK":"AI_PROMPT_RELEASED",target,trace);return map("saved",true);});}
 public Object ruleTest(AuthService.Session s,RuleTestInput i){return b.tx.execute(st->{b.auth.platform(s);return map("mode","OFFLINE_RULES_ONLY","result",inspect(i.source(),i.output(),true,List.of()),"supplierCalled",false);});}
}
